examples.template:
MonarchButton({{trigger}}) { isOpen = true }
    .sheet(isPresented: $isOpen) {
        NavigationStack {
            VStack(alignment: .leading, spacing: theme.spacing.space4) {
                Text({{description}})
                    .monarchTextStyle(.body)
                    .foregroundStyle(theme.colors.textMuted)
                MonarchTextField({{field}}, text: $email, prompt: {{placeholder}})
            }
            .padding(theme.spacing.space4)
            .frame(maxHeight: .infinity, alignment: .top)
            .navigationTitle({{title}})
            #if os(iOS)
            .navigationBarTitleDisplayMode(.inline)
            #endif
            .toolbar {
                ToolbarItem(placement: .cancellationAction) {
                    Button({{cancel}}) { isOpen = false }
                }
                ToolbarItem(placement: .confirmationAction) {
                    Button({{confirm}}) { isOpen = false }
                }
            }
        }
        .presentationDetents([.medium, .large])
        .presentationDragIndicator(.visible)
        .presentationBackground(theme.colors.bgSurface)
    }

examples.setupTemplate:
@Environment(\.monarchTheme) private var theme
@State private var isOpen = true
@State private var email = ""

examples.setup:
@Environment(\.monarchTheme) private var theme
@State private var isOpen = true
@State private var email = ""

examples.code:
MonarchButton("Invite people") { isOpen = true }
    .sheet(isPresented: $isOpen) {
        NavigationStack {
            VStack(alignment: .leading, spacing: theme.spacing.space4) {
                Text("They get an email with a link to join.")
                    .monarchTextStyle(.body)
                    .foregroundStyle(theme.colors.textMuted)
                MonarchTextField("Email address", text: $email, prompt: "name@example.com")
            }
            .padding(theme.spacing.space4)
            .frame(maxHeight: .infinity, alignment: .top)
            .navigationTitle("Invite people")
            #if os(iOS)
            .navigationBarTitleDisplayMode(.inline)
            #endif
            .toolbar {
                ToolbarItem(placement: .cancellationAction) {
                    Button("Cancel") { isOpen = false }
                }
                ToolbarItem(placement: .confirmationAction) {
                    Button("Send invite") { isOpen = false }
                }
            }
        }
        .presentationDetents([.medium, .large])
        .presentationDragIndicator(.visible)
        .presentationBackground(theme.colors.bgSurface)
    }
